const fileInput=document.getElementById("foto-input"),imgPreview=document.getElementById("img-preview"),placeholder=document.getElementById("placeholder-preview"),fileInfo=document.getElementById("file-info"),sidebarPreview=document.getElementById("sidebar-preview"),sidebarPlaceholder=document.getElementById("sidebar-placeholder");fileInput.addEventListener("change",function(){const e=this.files[0];if(e){const i=new FileReader;i.onload=function(e){imgPreview&&(imgPreview.src=e.target.result,imgPreview.classList.remove("hidden")),placeholder&&placeholder.classList.add("hidden"),sidebarPreview&&(sidebarPreview.src=e.target.result,sidebarPreview.classList.remove("hidden")),sidebarPlaceholder&&sidebarPlaceholder.classList.add("hidden")},i.readAsDataURL(e);const d=(e.size/1024).toFixed(1);fileInfo.innerHTML=`<span class="text-rose-600 font-bold">Terpilih: ${e.name} (${d} KB)</span>`}});